import '../models/models.dart';

class AnnualLyceeHistoryCivicsUnit {
  final SchoolLevel level;
  final String code, domain, title, lessonId, lessonTitle, summary, content;
  final int unitOrder;
  final List<String> keyPoints;
  final List<Exercise> exercises;
  const AnnualLyceeHistoryCivicsUnit({
    required this.level, required this.code, required this.domain,
    required this.unitOrder, required this.title, required this.lessonId,
    required this.lessonTitle, required this.summary, required this.content,
    required this.keyPoints, required this.exercises,
  });
  String get subjectId => 'core_${domain}_$code';
  String get chapterId => 'core_lycee_${domain}_${code}_unit_$unitOrder';
}

const annualLyceeHistoryCivicsUnits = <AnnualLyceeHistoryCivicsUnit>[
  AnnualLyceeHistoryCivicsUnit(level:SchoolLevel.seconde,code:'seconde',domain:'hg',unitOrder:1,title:'Méthodes d’étude historique et géographique',lessonId:'core_hg_2nde_sources_maps',lessonTitle:'Utiliser les sources et les cartes',summary:'Distinguer source, fait, interprétation et apprendre à lire une carte thématique.',content:'L’histoire étudie les sociétés du passé à partir de sources : textes, objets, images, témoignages et archives. Une source doit être située, identifiée et confrontée à d’autres documents. La géographie étudie les espaces et les relations entre sociétés et milieux. Pour lire une carte, observe le titre, l’échelle, la légende, l’orientation et la date. Un document apporte des informations, mais il faut vérifier son auteur, son contexte et ses limites.',keyPoints:['Identifier auteur, date, nature et contexte d’une source','Confronter plusieurs documents','Lire titre, échelle, légende et orientation d’une carte'],exercises:[
    Exercise(id:'core_hg_2nde_sm1',lessonId:'core_hg_2nde_sources_maps',question:'Pourquoi confronter plusieurs sources historiques ?',options:['Pour vérifier et nuancer les informations','Pour éviter toute analyse','Pour remplacer les faits par des opinions'],correctIndex:0,explanation:'Le croisement des sources permet de vérifier les informations et de comprendre leurs limites.'),
    Exercise(id:'core_hg_2nde_sm2',lessonId:'core_hg_2nde_sources_maps',question:'Quel élément explique les symboles d’une carte ?',options:['La légende','Le titre seul','La date seule'],correctIndex:0,explanation:'La légende explique les symboles et les couleurs.'),
    Exercise(id:'core_hg_2nde_sm3',lessonId:'core_hg_2nde_sources_maps',question:'Une source historique doit être étudiée en tenant compte…',options:['De son auteur et de son contexte','Uniquement de sa couleur','Seulement de sa longueur'],correctIndex:0,explanation:'L’auteur et le contexte aident à interpréter la source.'),
  ]),
  AnnualLyceeHistoryCivicsUnit(level:SchoolLevel.seconde,code:'seconde',domain:'hg',unitOrder:2,title:'Population, villes et développement',lessonId:'core_hg_2nde_population',lessonTitle:'Analyser la population et les espaces urbains',summary:'Comprendre la croissance démographique, les migrations et les défis de l’urbanisation.',content:'La population évolue selon les naissances, les décès et les migrations. La croissance démographique modifie les besoins en éducation, santé, logement et emploi. L’urbanisation correspond à l’augmentation de la population urbaine et à l’extension des villes. Les espaces urbains concentrent des activités et des services, mais peuvent connaître des difficultés d’accès à l’eau, de transport, de logement et de gestion des déchets. Une étude géographique s’appuie sur des données, des cartes et des graphiques datés.',keyPoints:['Évolution démographique : naissances, décès, migrations','Urbanisation : croissance et extension des villes','Analyser des données datées et leur source'],exercises:[
    Exercise(id:'core_hg_2nde_po1',lessonId:'core_hg_2nde_population',question:'Quels facteurs modifient la population ?',options:['Naissances, décès et migrations','La couleur des maisons','La forme des nuages'],correctIndex:0,explanation:'La population évolue par les naissances, les décès et les migrations.'),
    Exercise(id:'core_hg_2nde_po2',lessonId:'core_hg_2nde_population',question:'Quel défi peut accompagner l’urbanisation rapide ?',options:['Le besoin accru de logements et de services','La disparition de tous les besoins','L’absence de circulation'],correctIndex:0,explanation:'La croissance urbaine demande des logements, transports et services.'),
    Exercise(id:'core_hg_2nde_po3',lessonId:'core_hg_2nde_population',question:'Pour interpréter un graphique démographique, il faut vérifier…',options:['La date, l’unité et la source','Seulement la couleur','Le nom du dessinateur uniquement'],correctIndex:0,explanation:'La date, l’unité et la source sont indispensables à l’interprétation.'),
  ]),
  AnnualLyceeHistoryCivicsUnit(level:SchoolLevel.seconde,code:'seconde',domain:'ecm',unitOrder:1,title:'Citoyenneté, droits et devoirs',lessonId:'core_ecm_2nde_citizenship',lessonTitle:'Exercer sa citoyenneté de manière responsable',summary:'Relier droits, devoirs, libertés et responsabilité dans la vie collective.',content:'La citoyenneté désigne l’appartenance à une communauté politique et la participation à la vie collective. Les citoyens disposent de droits et de libertés protégés par les textes, et ont des devoirs : respecter la loi, les droits d’autrui et les biens publics. L’exercice responsable de la citoyenneté suppose de s’informer, de participer de façon pacifique, de respecter les opinions différentes et de rechercher des solutions légales aux conflits.',keyPoints:['Droits et libertés sont protégés par la loi','Respecter les droits d’autrui et les biens publics','Participer de façon pacifique et informée'],exercises:[
    Exercise(id:'core_ecm_2nde_ct1',lessonId:'core_ecm_2nde_citizenship',question:'Quel comportement relève de la citoyenneté responsable ?',options:['Respecter la loi et les droits d’autrui','Détruire un bien public','Diffuser une rumeur'],correctIndex:0,explanation:'Le respect de la loi et des droits d’autrui est une responsabilité civique.'),
    Exercise(id:'core_ecm_2nde_ct2',lessonId:'core_ecm_2nde_citizenship',question:'Une liberté s’exerce…',options:['Dans le respect des droits d’autrui et de la loi','Sans aucune limite','En imposant la violence'],correctIndex:0,explanation:'Les libertés doivent respecter les droits des autres et le cadre légal.'),
    Exercise(id:'core_ecm_2nde_ct3',lessonId:'core_ecm_2nde_citizenship',question:'Pour s’engager dans la vie collective, il faut d’abord…',options:['S’informer et participer pacifiquement','Refuser toute information','Empêcher les autres de parler'],correctIndex:0,explanation:'L’information et la participation pacifique favorisent la citoyenneté.'),
  ]),
  AnnualLyceeHistoryCivicsUnit(level:SchoolLevel.seconde,code:'seconde',domain:'ecm',unitOrder:2,title:'Institutions et biens publics',lessonId:'core_ecm_2nde_institutions',lessonTitle:'Comprendre les institutions et préserver les biens publics',summary:'Identifier le rôle des institutions et les responsabilités envers les équipements collectifs.',content:'Les institutions publiques sont organisées par la Constitution et les lois. Elles exercent des fonctions différentes : représenter, élaborer et appliquer les règles, administrer les services publics ou rendre la justice. Les biens publics et les équipements collectifs servent à la communauté. Les préserver, signaler les dégradations et demander des comptes par des voies légales contribuent à la bonne gouvernance.',keyPoints:['Les institutions ont des compétences définies','Les services publics répondent à des besoins collectifs','Préserver les biens publics et demander des comptes légalement'],exercises:[
    Exercise(id:'core_ecm_2nde_in1',lessonId:'core_ecm_2nde_institutions',question:'Pourquoi les institutions ont-elles des compétences définies ?',options:['Pour organiser les responsabilités publiques','Pour empêcher toute règle','Pour remplacer les citoyens'],correctIndex:0,explanation:'Les compétences définies permettent d’organiser les responsabilités et les contrôles.'),
    Exercise(id:'core_ecm_2nde_in2',lessonId:'core_ecm_2nde_institutions',question:'Quel exemple est un bien public ?',options:['Une route publique','Un cahier personnel','Un téléphone privé'],correctIndex:0,explanation:'Une route publique est un équipement collectif.'),
    Exercise(id:'core_ecm_2nde_in3',lessonId:'core_ecm_2nde_institutions',question:'Comment signaler une mauvaise gestion ?',options:['Par les voies légales et les mécanismes de contrôle','Par la violence','En détruisant les documents'],correctIndex:0,explanation:'Les mécanismes légaux permettent de signaler et de contrôler la gestion publique.'),
  ]),
  AnnualLyceeHistoryCivicsUnit(level:SchoolLevel.premiere,code:'premiere',domain:'hg',unitOrder:1,title:'Colonisation et décolonisation en Afrique',lessonId:'core_hg_1ere_decolonization',lessonTitle:'Analyser les causes et les étapes de la décolonisation',summary:'Comprendre les facteurs de la décolonisation et les transformations politiques en Afrique.',content:'Après la Seconde Guerre mondiale, les mouvements nationalistes, les changements internationaux, les revendications des populations colonisées et les difficultés des puissances coloniales accélèrent la décolonisation. Les processus varient selon les territoires : négociations, mobilisations, conflits et transitions politiques. Les indépendances ouvrent de nouveaux défis : construire des institutions, développer l’économie, préserver l’unité nationale et établir des relations internationales. L’étude doit comparer les situations et distinguer les dates, les acteurs et les conséquences.',keyPoints:['Nationalismes et revendications d’autodétermination','Contexte international après 1945','Des processus différents selon les territoires','Défis des États indépendants'],exercises:[
    Exercise(id:'core_hg_1ere_dc1',lessonId:'core_hg_1ere_decolonization',question:'Quel facteur a favorisé la décolonisation après 1945 ?',options:['Les revendications d’autodétermination','La disparition de toutes les populations','L’arrêt de toute politique'],correctIndex:0,explanation:'Les revendications d’autodétermination ont joué un rôle majeur.'),
    Exercise(id:'core_hg_1ere_dc2',lessonId:'core_hg_1ere_decolonization',question:'Les processus de décolonisation ont été…',options:['Différents selon les territoires','Identiques partout','Sans acteurs locaux'],correctIndex:0,explanation:'Les trajectoires ont varié : négociations, mobilisations ou conflits.'),
    Exercise(id:'core_hg_1ere_dc3',lessonId:'core_hg_1ere_decolonization',question:'Quel défi suit souvent l’indépendance ?',options:['Construire des institutions et développer le pays','Supprimer toute administration','Éviter toute relation internationale'],correctIndex:0,explanation:'Les nouveaux États doivent construire leurs institutions et leur développement.'),
  ]),
  AnnualLyceeHistoryCivicsUnit(level:SchoolLevel.premiere,code:'premiere',domain:'hg',unitOrder:2,title:'Intégration régionale et développement',lessonId:'core_hg_1ere_regional_integration',lessonTitle:'Étudier la coopération en Afrique de l’Ouest',summary:'Comprendre les objectifs de la coopération régionale et ses défis.',content:'La coopération régionale vise à faciliter les échanges, la mobilité, la sécurité et les projets communs. En Afrique de l’Ouest, la CEDEAO rassemble des États pour coordonner certaines politiques et favoriser l’intégration. Les obstacles peuvent inclure les différences de développement, les infrastructures insuffisantes, les tensions politiques et les difficultés de mise en œuvre. Une analyse équilibrée présente les objectifs, les réalisations, les limites et les perspectives.',keyPoints:['La coopération facilite échanges et actions communes','La CEDEAO est une organisation régionale ouest-africaine','Analyser réalisations et limites'],exercises:[
    Exercise(id:'core_hg_1ere_ri1',lessonId:'core_hg_1ere_regional_integration',question:'Quel est un objectif de l’intégration régionale ?',options:['Faciliter les échanges et la coopération','Isoler tous les pays','Supprimer les infrastructures'],correctIndex:0,explanation:'L’intégration cherche à faciliter les échanges et les actions communes.'),
    Exercise(id:'core_hg_1ere_ri2',lessonId:'core_hg_1ere_regional_integration',question:'La CEDEAO est…',options:['Une organisation régionale ouest-africaine','Une ville du Togo','Une entreprise privée'],correctIndex:0,explanation:'La CEDEAO est une organisation de coopération des États d’Afrique de l’Ouest.'),
    Exercise(id:'core_hg_1ere_ri3',lessonId:'core_hg_1ere_regional_integration',question:'Une analyse géographique équilibrée présente…',options:['Les objectifs, réalisations et limites','Seulement les réussites','Seulement les opinions'],correctIndex:0,explanation:'Une analyse complète examine aussi bien les réussites que les limites.'),
  ]),
  AnnualLyceeHistoryCivicsUnit(level:SchoolLevel.premiere,code:'premiere',domain:'ecm',unitOrder:1,title:'Droits humains et libertés publiques',lessonId:'core_ecm_1ere_rights',lessonTitle:'Protéger les droits humains et les libertés',summary:'Identifier les droits fondamentaux et les moyens de les protéger.',content:'Les droits humains sont universels et reposent sur la dignité de chaque personne. Ils comprennent notamment le droit à la vie, à l’éducation, à la liberté d’expression, à la sécurité et à l’égalité. Les libertés publiques s’exercent dans un cadre légal qui protège aussi les droits d’autrui. Les institutions, les tribunaux, les organisations de la société civile et les mécanismes internationaux peuvent contribuer à leur protection.',keyPoints:['Dignité et égalité de chaque personne','Libertés publiques et responsabilité','Institutions et mécanismes de protection'],exercises:[
    Exercise(id:'core_ecm_1ere_rh1',lessonId:'core_ecm_1ere_rights',question:'Sur quel principe reposent les droits humains ?',options:['La dignité de chaque personne','La richesse uniquement','L’appartenance à un groupe seulement'],correctIndex:0,explanation:'Les droits humains reposent sur la dignité et l’égalité de chaque personne.'),
    Exercise(id:'core_ecm_1ere_rh2',lessonId:'core_ecm_1ere_rights',question:'La liberté d’expression doit…',options:['Respecter les droits d’autrui et la loi','Autoriser les menaces','Supprimer toute responsabilité'],correctIndex:0,explanation:'La liberté d’expression s’exerce dans le respect des droits et du cadre légal.'),
    Exercise(id:'core_ecm_1ere_rh3',lessonId:'core_ecm_1ere_rights',question:'Quel acteur peut contribuer à protéger les droits ?',options:['Les tribunaux','Les groupes qui violent la loi','Les auteurs de discrimination'],correctIndex:0,explanation:'Les tribunaux et autres mécanismes de protection contribuent au respect des droits.'),
  ]),
  AnnualLyceeHistoryCivicsUnit(level:SchoolLevel.premiere,code:'premiere',domain:'ecm',unitOrder:2,title:'Démocratie, pluralisme et participation',lessonId:'core_ecm_1ere_democracy',lessonTitle:'Participer au débat démocratique',summary:'Comprendre pluralisme, débat public, élections et responsabilité citoyenne.',content:'Le pluralisme permet l’existence de plusieurs opinions, partis et organisations. Un débat démocratique repose sur des informations vérifiables, l’écoute, l’argumentation et le respect des personnes. La participation peut prendre plusieurs formes : vote selon les conditions légales, consultation, association, débat public et action communautaire. La désinformation, l’intimidation et la violence affaiblissent la confiance et la participation.',keyPoints:['Pluralisme : diversité des opinions et organisations','Débat fondé sur des faits et le respect','Participation pacifique et responsable'],exercises:[
    Exercise(id:'core_ecm_1ere_dm1',lessonId:'core_ecm_1ere_democracy',question:'Le pluralisme signifie…',options:['La coexistence de plusieurs opinions et organisations','Une seule opinion obligatoire','L’absence de débat'],correctIndex:0,explanation:'Le pluralisme reconnaît la diversité des opinions et organisations.'),
    Exercise(id:'core_ecm_1ere_dm2',lessonId:'core_ecm_1ere_democracy',question:'Un débat démocratique doit s’appuyer sur…',options:['Des informations vérifiables et le respect','Des insultes','Des rumeurs seulement'],correctIndex:0,explanation:'Les faits et le respect des personnes favorisent un débat constructif.'),
    Exercise(id:'core_ecm_1ere_dm3',lessonId:'core_ecm_1ere_democracy',question:'Quel comportement affaiblit la participation ?',options:['L’intimidation et la désinformation','L’écoute active','L’accès à l’information'],correctIndex:0,explanation:'L’intimidation et la désinformation nuisent à la confiance démocratique.'),
  ]),
  AnnualLyceeHistoryCivicsUnit(level:SchoolLevel.terminale,code:'terminale',domain:'hg',unitOrder:1,title:'L’ONU et les relations internationales depuis 1945',lessonId:'core_hg_tle_un',lessonTitle:'Naissance, fonctionnement et limites de l’ONU',summary:'Expliquer la création de l’ONU, ses organes et son rôle dans la paix internationale.',content:'L’Organisation des Nations Unies est fondée en 1945 après la Seconde Guerre mondiale pour maintenir la paix, développer la coopération et promouvoir les droits humains. Ses principaux organes comprennent l’Assemblée générale, le Conseil de sécurité, le Secrétariat, la Cour internationale de Justice, le Conseil économique et social et le Conseil de tutelle. Le Conseil de sécurité a une responsabilité particulière dans la paix et la sécurité. L’ONU mène des actions diplomatiques, humanitaires et de maintien de la paix, mais son efficacité peut être limitée par les rivalités entre États et le droit de veto.',keyPoints:['ONU fondée en 1945','Six organes principaux','Maintien de la paix et coopération','Limites liées aux intérêts et rivalités des États'],exercises:[
    Exercise(id:'core_hg_tle_un1',lessonId:'core_hg_tle_un',question:'En quelle année l’ONU est-elle fondée ?',options:['1945','1919','1960'],correctIndex:0,explanation:'L’ONU est fondée en 1945 après la Seconde Guerre mondiale.'),
    Exercise(id:'core_hg_tle_un2',lessonId:'core_hg_tle_un',question:'Quel organe de l’ONU est chargé principalement de la paix et de la sécurité internationales ?',options:['Conseil de sécurité','Secrétariat uniquement','Cour de commerce'],correctIndex:0,explanation:'Le Conseil de sécurité a la responsabilité principale du maintien de la paix et de la sécurité.'),
    Exercise(id:'core_hg_tle_un3',lessonId:'core_hg_tle_un',question:'Quelle limite peut freiner l’action de l’ONU ?',options:['Les rivalités entre États et le droit de veto','L’existence de débats','La coopération humanitaire'],correctIndex:0,explanation:'Les désaccords entre États et le droit de veto peuvent bloquer certaines décisions.'),
  ]),
  AnnualLyceeHistoryCivicsUnit(level:SchoolLevel.terminale,code:'terminale',domain:'hg',unitOrder:2,title:'Décolonisation de l’Afrique et évolution du Togo',lessonId:'core_hg_tle_togo',lessonTitle:'De la décolonisation à l’évolution politique du Togo',summary:'Situer les indépendances africaines et les principales étapes de l’histoire politique du Togo.',content:'La décolonisation de l’Afrique s’accélère après 1945 sous l’effet des mouvements nationalistes, des changements internationaux et des revendications d’autodétermination. Le Togo accède à l’indépendance le 27 avril 1960. L’histoire postcoloniale du pays comprend la construction des institutions, les transformations politiques et les enjeux de développement. Pour étudier l’évolution politique, il faut distinguer les périodes, les acteurs, les événements et les conséquences, en croisant les sources historiques.',keyPoints:['Décolonisation accélérée après 1945','Indépendance du Togo : 27 avril 1960','Étudier les périodes et les acteurs avec des sources'],exercises:[
    Exercise(id:'core_hg_tle_tg1',lessonId:'core_hg_tle_togo',question:'À quelle date le Togo accède-t-il à l’indépendance ?',options:['27 avril 1960','24 octobre 1945','1er janvier 1970'],correctIndex:0,explanation:'Le Togo devient indépendant le 27 avril 1960.'),
    Exercise(id:'core_hg_tle_tg2',lessonId:'core_hg_tle_togo',question:'Quel facteur a contribué à la décolonisation ?',options:['Les mouvements nationalistes et les revendications d’autodétermination','La disparition de toutes les revendications','L’absence de changements après 1945'],correctIndex:0,explanation:'Les mouvements nationalistes ont joué un rôle important dans les indépendances.'),
    Exercise(id:'core_hg_tle_tg3',lessonId:'core_hg_tle_togo',question:'Pour analyser l’évolution politique, il faut…',options:['Croiser les sources et distinguer les périodes','Confondre tous les événements','Se baser sur une rumeur'],correctIndex:0,explanation:'La méthode historique exige des sources et une chronologie rigoureuse.'),
  ]),
  AnnualLyceeHistoryCivicsUnit(level:SchoolLevel.terminale,code:'terminale',domain:'ecm',unitOrder:1,title:'Droits humains et culture de la paix',lessonId:'core_ecm_tle_peace',lessonTitle:'Promouvoir la paix et les droits humains',summary:'Relier droits humains, règlement pacifique des conflits et coopération internationale.',content:'La culture de la paix repose sur la justice, la liberté, le respect des droits humains et la non-violence. Les conflits peuvent être traités par le dialogue, la médiation, la négociation et les procédures juridiques. Les organisations internationales et régionales peuvent soutenir la coopération, l’aide humanitaire et la prévention des conflits. La paix durable demande aussi de lutter contre les discriminations, de protéger les civils et de favoriser l’accès équitable aux services essentiels.',keyPoints:['Droits humains, justice et non-violence','Dialogue, médiation et négociation','Coopération internationale et protection des civils'],exercises:[
    Exercise(id:'core_ecm_tle_p1',lessonId:'core_ecm_tle_peace',question:'Quel moyen permet un règlement pacifique d’un conflit ?',options:['La médiation','La menace','La vengeance'],correctIndex:0,explanation:'La médiation aide les parties à rechercher une solution pacifique.'),
    Exercise(id:'core_ecm_tle_p2',lessonId:'core_ecm_tle_peace',question:'La culture de la paix exige…',options:['Le respect des droits et la non-violence','La discrimination','La violence systématique'],correctIndex:0,explanation:'La culture de la paix s’appuie sur les droits, la justice et la non-violence.'),
    Exercise(id:'core_ecm_tle_p3',lessonId:'core_ecm_tle_peace',question:'La protection des civils en conflit est…',options:['Un enjeu humanitaire et juridique','Un acte sans importance','Une tâche réservée aux élèves'],correctIndex:0,explanation:'La protection des civils est un principe humanitaire essentiel.'),
  ]),
  AnnualLyceeHistoryCivicsUnit(level:SchoolLevel.terminale,code:'terminale',domain:'ecm',unitOrder:2,title:'Gouvernance, intégrité et responsabilité',lessonId:'core_ecm_tle_governance',lessonTitle:'Comprendre la bonne gouvernance',summary:'Identifier transparence, responsabilité, contrôle et lutte contre la corruption.',content:'La bonne gouvernance repose sur la transparence, la responsabilité, la participation, l’État de droit et l’efficacité des services publics. La corruption est l’abus d’une fonction ou d’un pouvoir pour obtenir un avantage privé. Elle peut affaiblir la confiance, détourner les ressources et aggraver les inégalités. La prévention passe par des règles claires, des contrôles indépendants, la publication d’informations, la protection des lanceurs d’alerte selon la loi et l’intégrité personnelle.',keyPoints:['Transparence et responsabilité','État de droit et mécanismes de contrôle','Corruption : abus de pouvoir pour un avantage privé','Intégrité et protection des ressources publiques'],exercises:[
    Exercise(id:'core_ecm_tle_gv1',lessonId:'core_ecm_tle_governance',question:'La transparence consiste notamment à…',options:['Rendre les informations publiques pertinentes accessibles','Cacher systématiquement les décisions','Refuser tout contrôle'],correctIndex:0,explanation:'La transparence permet aux citoyens de comprendre et contrôler les décisions publiques.'),
    Exercise(id:'core_ecm_tle_gv2',lessonId:'core_ecm_tle_governance',question:'La corruption est…',options:['L’abus d’une fonction pour un avantage privé','Le respect des règles','La publication d’un budget'],correctIndex:0,explanation:'La corruption utilise abusivement un pouvoir ou une fonction à des fins privées.'),
    Exercise(id:'core_ecm_tle_gv3',lessonId:'core_ecm_tle_governance',question:'Quel mécanisme favorise la bonne gouvernance ?',options:['Un contrôle indépendant et des comptes rendus','L’absence de règles','Le favoritisme illégal'],correctIndex:0,explanation:'Le contrôle et la reddition de comptes favorisent la responsabilité.'),
  ]),
