final annualLyceeHistoryCivicsChapters = annualLyceeHistoryCivicsUnits.map((unit) => Chapter(
  id:unit.chapterId,subjectId:unit.subjectId,title:'Unité ${unit.unitOrder} — ${unit.title}',
  order:unit.unitOrder,term: termForAnnualUnit(unit.unitOrder, annualLyceeHistoryCivicsUnits.where((item) => item.code == unit.code && item.domain == unit.domain).length),totalLessons:1,
)).toList();

final annualLyceeHistoryCivicsLessons = annualLyceeHistoryCivicsUnits.map((unit) => Lesson(
  id:unit.lessonId,chapterId:unit.chapterId,title:unit.lessonTitle,
  summary:unit.summary,content:unit.content,keyPoints:unit.keyPoints,durationMinutes:30,
)).toList();

final annualLyceeHistoryCivicsExercises = annualLyceeHistoryCivicsUnits.expand((unit)=>unit.exercises).toList();
